import React, { Component } from 'react';

const SudokuBoard = ({ board, solution, showSolution, onCellChange }) => (
  <div className="board">
    {
      board.map((cell, i) => {
        return (
          <div className="cell">
            <input
              type="text"
              pattern="\d*"
              novalidate=""
              id={`input-${i}`}
              value={showSolution ? solution[i] : cell}
              maxlength="1"
              onChange={() => onCellChange(i, cell)}
            />
          </div>
        )
      })
    }
  </div>
);

export default SudokuBoard;
